+.hero-actions,
+.walkthrough-controls,
+.walkthrough-finish,
+.comparison-actions,
+.repair-jumps {
+  display: flex;
+  flex-wrap: wrap;
+  align-items: center;
+  gap: 12px;
+}
+
+.hero-copy .hero-note {
+  display: block;
+  margin: 18px 0 0;
+}
+
+.hero-note a {
+  text-decoration: underline;
+  text-underline-offset: 4px;
+}
+
+.rl-walkthrough {
+  padding: 36px 0 48px;
+  border-top: 1px solid var(--line);
+  scroll-margin-top: 20px;
+}
+
+.walkthrough-heading {
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+  flex-wrap: wrap;
+  gap: 12px;
+}
+
+.walkthrough-stages {
+  display: grid;
+  grid-template-columns: repeat(5, minmax(0, 1fr));
+  gap: 8px;
+  margin: 24px 0;
+}
+
+.walkthrough-stages [aria-current],
+.walkthrough-stages [aria-current]:hover {
+  background: var(--yellow);
+  border-color: var(--ink);
+}
+
+.walkthrough-body {
+  display: grid;
+  grid-template-columns: minmax(0, 1fr) minmax(0, 1.3fr);
+  align-items: start;
+  gap: 32px;
+}
+
+.walkthrough-body>.world {
+  padding: 22px;
+  border: 1px solid var(--line);
+  border-radius: var(--radius);
+  background: #f2f7ef;
+  min-height: 390px;
+}
+
+.walkthrough-disclaimer,
+.comparison-note,
+.recipe-source p {
+  font-size: 16px;
+  color: var(--muted);
+}
+
+.walkthrough-prompt {
+  margin: 16px 0;
+  padding: 12px;
+  background: white;
+  border-radius: 8px;
+}
+
+.walkthrough-samples {
+  display: grid;
+  grid-template-columns: repeat(4, minmax(0, 1fr));
+  gap: 8px;
+}
+
+.walkthrough-sample {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  padding: 8px 2px;
+  background: white;
+  border: 1px solid var(--line);
+  border-radius: 8px;
+  font-size: 15px;
+}
+
+.walkthrough-sample strong {
+  font-size: 21px;
+}
+
+.walkthrough-sample.correct {
+  background: #d8efd9;
+  border-color: #7ca982;
+}
+
+.walkthrough-sample.incorrect {
+  background: #fbebe2;
+}
+
+.walkthrough-update {
+  padding: 16px 0;
+  font-size: 16px;
+  overflow-wrap: anywhere;
+}
+
+[data-tour-phase="1"] .sampler,
+[data-tour-phase="3"] .trainer,
+[data-tour-phase="4"] .flow-arrow {
+  outline: 3px solid #bf9200;
+  outline-offset: 2px;
+}
+
+.walkthrough-controls,
+.walkthrough-finish {
+  margin-top: 24px;
+}
+
+.comparison,
+.recipe-source {
+  padding: 20px;
+  margin: 22px 0;
+  border: 1px solid var(--line);
+  border-radius: 12px;
+  background: #fff;
+}
+
+.comparison summary,
+.recipe-source summary,
+.repair-preview summary {
+  cursor: pointer;
+  font-weight: 700;
+}
+
+.comparison-pair {
+  display: grid;
+  grid-template-columns: repeat(2, minmax(0, 1fr));
+  gap: 16px;
+  margin: 20px 0;
+}
+
+.comparison-config {
+  padding: 16px;
+  border-radius: 12px;
+  background: var(--paper);
+  min-width: 0;
+}
+
+.comparison-config p,
+.comparison-config li,
+.comparison-insights,
+.config-differences,
+.recipe-source dl {
+  font-size: 16px;
+  overflow-wrap: anywhere;
+}
+
+.comparison-switch {
+  display: none;
+}
+
+.config-differences {
+  list-style: none;
+  padding: 0;
+}
+
+.config-differences li {
+  display: flex;
+  flex-wrap: wrap;
+  justify-content: space-between;
+  gap: 8px 16px;
+  padding: 10px 0;
+  border-bottom: 1px solid var(--line);
+}
+
+.repair-issue {
+  padding: 18px;
+  margin: 16px 0;
+  background: #fff9e8;
+  border: 1px solid #d9cda6;
+  border-radius: 12px;
+}
+
+.repair-issue h3 {
+  margin: 0 0 12px;
+  font-size: 18px;
+}
+
+.repair-preview {
+  padding: 16px 0 4px;
+  font-size: 16px;
+  overflow-wrap: anywhere;
+}
+
+.recipe-source dt {
+  font-weight: 700;
+  margin-top: 14px;
+}
+
+.recipe-source dd {
+  margin-left: 0;
+}
+
+.recipe-source a {
+  text-decoration: underline;
+}
+
+@media (max-width: 720px) {
+  .site-header .install-nav {
+    display: none;
+  }
+
+  .walkthrough-body,
+  .comparison-pair {
+    grid-template-columns: minmax(0, 1fr);
+  }
+
+  .walkthrough-stages {
+    grid-template-columns: repeat(3, minmax(0, 1fr));
+  }
+
+  .walkthrough-body>.world,
+  .comparison,
+  .comparison-config {
+    padding: 12px;
+  }
+
+  .comparison-switch {
+    display: flex;
+    flex-wrap: wrap;
+    gap: 8px;
+    margin-top: 18px;
+  }
+
+  .comparison-switch [aria-pressed="true"] {
+    background: var(--yellow);
+  }
+
+  .comparison-config:not(.selected) {
+    display: none;
+  }
+}
+
